package com.imageseal.controller;
import com.imageseal.repository.AuditLogRepository;import com.imageseal.security.UserPrincipal;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/audit-logs") public class AuditController {private final AuditLogRepository audit;public AuditController(AuditLogRepository audit){this.audit=audit;}@GetMapping public List<Map<String,Object>> list(@AuthenticationPrincipal UserPrincipal p){return audit.findAllByOwnerIdOrderByCreatedAtDesc(p.id()).stream().map(a->Map.<String,Object>of("id",a.getId(),"action",a.getAction(),"resource_id",Objects.requireNonNullElse(a.getResourceId(),""),"created_at",a.getCreatedAt())).toList();}}
